from typing import List

def separateSquares(squares: List[List[int]]) -> float:
    total_area = 0
    for _, y, l in squares:
        total_area += l * l
    target = total_area / 2.0

    # The range of possible y-coordinates is between the minimum bottom and maximum top
    low = float(min(s[1] for s in squares))
    high = float(max(s[1] + s[2] for s in squares))

    for _ in range(100):
        mid = (low + high) / 2
        current_below = 0.0
        for _, y, l in squares:
            top = y + l
            if mid <= y:
                # Line is below the square entirely
                current_below += 0
            elif mid >= top:
                # Line is above the square entirely
                current_below += l * l
            else:
                # Line cuts through the square
                current_below += (mid - y) * l

        if current_below < target:
            low = mid
        else:
            high = mid

    return low
