from typing import List

def minValidStrings(words: List[str], target: str) -> int:
    # 建立 Trie 結構儲存所有 words 的前綴
    trie = {}
    for w in words:
        node = trie
        for char in w:
            if char not in node:
                node[char] = {}
            node = node[char]

    n = len(target)
    # dp[i] 表示形成 target[:i] 所需的最少字串數量
    # 初始化為無限大，dp[0] 為 0 (空字串需要 0 個)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == float('inf'):
            continue

        # 從當前位置 i 開始，嘗試匹配所有可能的前綴
        node = trie
        for j in range(i, n):
            char = target[j]
            if char not in node:
                break
            node = node[char]
            # 如果 target[i:j+1] 是某個 words 的前綴，更新 dp[j+1]
            dp[j + 1] = min(dp[j + 1], dp[i] + 1)

    return int(dp[n]) if dp[n] != float('inf') else -1
