from typing import List

def minValidStrings(words: List[str], target: str) -> int:
    # Build a Trie of all prefixes. 
    # Actually, since any prefix of words[i] is valid, we just need to know 
    # if a string is a prefix of ANY word in the list.
    # A simpler way is to store all words in a Trie and check paths.
    trie = {}
    for w in words:
        node = trie
        for char in w:
            if char not in node:
                node[char] = {}
            node = node[char]

    n = len(target)
    # dp[i] is the min strings to form target[:i]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == float('inf'):
            continue

        # Try to find the longest prefix of target[i:] that exists in our Trie
        node = trie
        for j in range(i, n):
            char = target[j]
            if char in node:
                node = node[char]
                dp[j + 1] = min(dp[j + 1], dp[i] + 1)
            else:
                break

    return dp[n] if dp[n] != float('inf') else -1
