from typing import List

def maxFrequency(nums: List[int], k: int) -> int:
    initial_k_count = 0
    for x in nums:
        if x == k:
            initial_k_count += 1

    max_gain = 0
    # We want to find a subarray that maximizes (count of v - count of k)
    # for some value v != k.
    # Let's iterate through all unique values in nums except k.
    unique_vals = set(nums)
    if k in unique_vals:
        unique_vals.remove(k)

    for v in unique_vals:
        current_gain = 0
        max_v_gain = 0
        # Kadane's algorithm logic:
        # Treat every occurrence of v as +1 and every occurrence of k as -1
        for x in nums:
            if x == v:
                current_gain += 1
            elif x == k:
                current_gain -= 1

            if current_gain < 0:
                current_gain = 0
            if current_gain > max_v_gain:
                max_v_gain = current_gain

        if max_v_gain > max_gain:
            max_gain = max_v_gain

    return initial_k_count + max_gain

